def precision_recall(y_true, y_pred):
    tp = fp = fn = 0
    for a, p in zip(y_true, y_pred):
        if p == 1 and a == 1:
            tp += 1
        elif p == 1 and a == 0:
            fp += 1
        elif p == 0 and a == 1:
            fn += 1
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    return [round(precision, 2), round(recall, 2)]
